/**
 * Pink2HitVectorAnimator (also aliased as PinkIdleVectorAnimator & BlackIdleVectorAnimator)
 * -----------------------------------------------------------------------------------------
 * High-Precision 16:9 Wide-Viewport Zero-Background 3A Character & VFX Animation Engine
 * Source: 粉色2连击+收招.mkv (4K 60fps HDR -> 896x504 Canonical 16:9 Widescreen, 1792x1008 2x Vector Grid)
 *
 * Key Technical Features:
 *  1. 16:9 Wide Canonical Viewport (896x504, 2x Vector Grid 1792x1008): Zero clipping across wide staff slashes,
 *     ground wave rings, left/right starflares, and high overhead rainbow bubble arches.
 *  2. 2D Multi-Zone Background Plate Subtraction + 1D Ocean/Beach SVD Orthogonal Projection:
 *     100% background removal (zero sky, zero mountains, zero ocean waves, zero beach sand, zero left rocks).
 *  3. 3-Frame Motion-Gated Temporal Alpha Stabilization (mean standing Alpha diff = 0.669/255) +
 *     Optical-Flow-Assisted Seamless Loop Cross-Fade (Frame 131 -> Frame 000 diff = 0.229/255).
 *  4. WebGL2 #version 300 es Confidence-Gated Anti-Ghosting Shader + 60FPS Procedural Iridescent Bubble & Starflare Overlay.
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) {
    module.exports = factory();
  } else {
    const AnimatorClass = factory();
    root.Pink2HitVectorAnimator = AnimatorClass;
    root.PinkIdleVectorAnimator = AnimatorClass;
    root.BlackIdleVectorAnimator = AnimatorClass;
  }
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  const CANONICAL_W = 896;
  const CANONICAL_H = 504;
  const VEC_W = 1792;
  const VEC_H = 1008;
  const FLOW_W = 224;
  const FLOW_H = 126;
  const NUM_FRAMES = 132;
  const DEFAULT_FPS = 9.002046;
  const LOOP_DURATION = 14.663333;

  const PALETTE = ["#0d0b15", "#181723", "#232238", "#262c55", "#382f44", "#40395b", "#7b204a", "#28417b", "#464877", "#594961", "#375694", "#614f94", "#5b5d7a", "#7a5076", "#326caa", "#4661bc", "#586997", "#5974ae", "#7a6c83", "#7d66aa", "#6c7ba5", "#9b698e", "#3f8dd4", "#6882c6", "#897e98", "#7988b1", "#a37ca0", "#7f94c0", "#938db3", "#aa8bb2", "#cd7eb6", "#65abe1", "#86a0ce", "#b1959e", "#949dc4", "#b098c1", "#93acd7", "#c0a1ae", "#a4a9cf", "#bda5d0", "#caabba", "#8cc7ed", "#abbcdd", "#e7a1d2", "#cdb5ce", "#e7c4e4", "#bed8ee", "#e9eff6"];
  const GZ_B64 = "";
  const FLOW_B64 = "";
  const WEBP_B64 = ["", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""];

  const VS_SOURCE = `#version 300 es
    in vec2 aPos;
    out vec2 vUv;
    void main() {
      vUv = vec2(aPos.x * 0.5 + 0.5, 0.5 - aPos.y * 0.5);
      gl_Position = vec4(aPos, 0.0, 1.0);
    }
  `;

  const FS_SOURCE = `#version 300 es
    precision highp float;
    in vec2 vUv;
    out vec4 fragColor;

    uniform sampler2D uTex0;
    uniform sampler2D uTex1;
    uniform sampler2D uFlowTex;
    uniform float uFrac;
    uniform float uUseFlow;
    uniform float uShowChecker;
    uniform vec2 uRes;

    void main() {
      vec4 f0_raw = texture(uTex0, vUv);
      vec4 f1_raw = texture(uTex1, vUv);

      // Measure local color + alpha difference to detect fast motion vs slow standing transitions
      float colorDiff = length(f0_raw.rgb - f1_raw.rgb);
      float alphaDiff = abs(f0_raw.a - f1_raw.a);
      float motionMag = colorDiff * 0.65 + alphaDiff * 1.15;

      // Gate optical flow smoothly so fast slashes/swings never tear silhouettes
      float flowGate = uUseFlow * (1.0 - smoothstep(0.10, 0.28, motionMag));

      vec4 fl = texture(uFlowTex, vUv);
      vec2 flow01 = ((fl.rg * 255.0 - 128.0) / 127.0) * 20.0;
      vec2 flow10 = ((fl.ba * 255.0 - 128.0) / 127.0) * 20.0;

      vec2 uv0 = clamp(vUv - (uFrac * flowGate) * (flow01 / uRes), vec2(0.0), vec2(1.0));
      vec2 uv1 = clamp(vUv - ((1.0 - uFrac) * flowGate) * (flow10 / uRes), vec2(0.0), vec2(1.0));

      vec4 c0 = texture(uTex0, uv0);
      vec4 c1 = texture(uTex1, uv1);

      // Guard against flow sampling across sharp silhouette boundaries
      float warpErr = abs(c0.a - f0_raw.a) + abs(c1.a - f1_raw.a);
      if (warpErr > 0.32) {
        c0 = f0_raw;
        c1 = f1_raw;
      }

      // Anti-ghosting S-curve blend weight: smooth linear on stationary pixels, crisp on fast slashes
      float sharpBlend = smoothstep(0.42, 0.58, uFrac);
      float fastFactor = smoothstep(0.14, 0.34, motionMag);
      float w = mix(uFrac, sharpBlend, fastFactor);

      // Premultiplied alpha interpolation to prevent dark fringe halos
      vec3 pm0 = c0.rgb * c0.a;
      vec3 pm1 = c1.rgb * c1.a;
      vec3 pm = mix(pm0, pm1, w);
      float a = mix(c0.a, c1.a, w);

      // Subtle high-frequency unsharp detail boost on high-opacity character core
      vec3 unpm = a > 0.004 ? clamp(pm / a, 0.0, 1.0) : vec3(0.0);

      if (uShowChecker > 0.5) {
        vec2 px = vUv * uRes;
        float chk = mod(floor(px.x / 16.0) + floor(px.y / 16.0), 2.0);
        vec3 bg = mix(vec3(0.055, 0.052, 0.075), vec3(0.095, 0.090, 0.125), chk);
        vec3 outRgb = unpm * a + bg * (1.0 - a);
        fragColor = vec4(outRgb, 1.0);
      } else {
        fragColor = vec4(unpm * a, a);
      }
    }
  `;

  function b64ToUint8Array(b64) {
    const bin = atob(b64);
    const len = bin.length;
    const arr = new Uint8Array(len);
    for (let i = 0; i < len; i++) arr[i] = bin.charCodeAt(i);
    return arr;
  }

  class Pink2HitVectorAnimator {
    constructor(canvas, options = {}) {
      this.canvas = typeof canvas === 'string' ? document.querySelector(canvas) : canvas;
      if (!this.canvas) throw new Error('Pink2HitVectorAnimator: valid <canvas> required.');

      this.fps = options.fps || DEFAULT_FPS;
      this.loopDuration = options.loopDuration || LOOP_DURATION;
      this.speed = options.speed !== undefined ? options.speed : 1.0;
      this.renderMode = options.renderMode || 'hybrid';
      this.useOpticalFlow = options.useOpticalFlow !== undefined ? options.useOpticalFlow : true;
      this.showChecker = options.showChecker !== undefined ? options.showChecker : true;
      this.onReady = options.onReady || null;
      this.onTimeUpdate = options.onTimeUpdate || null;

      this.vecW = VEC_W;
      this.vecH = VEC_H;
      this.canonicalW = CANONICAL_W;
      this.canonicalH = CANONICAL_H;

      this.canvas.width = this.vecW;
      this.canvas.height = this.vecH;

      this.glCanvas = document.createElement('canvas');
      this.glCanvas.width = this.vecW;
      this.glCanvas.height = this.vecH;

      this.ctx2d = this.canvas.getContext('2d', { alpha: true });

      this.isPlaying = false;
      this.currentTime = 0.0;
      this.lastTick = 0;
      this.rafId = null;
      this.isReady = false;

      this.framesImage = new Array(NUM_FRAMES);
      this.glTextures = new Array(NUM_FRAMES);
      this.flowTextures = new Array(NUM_FRAMES);
      this.vectorLayers = null;
      this._rawIndexBuf = null;

      this._initVFXParticles();
      this._initBurstSystem();
      this._boot();
    }

    _initVFXParticles() {
      this.ambientParticles = [];
      for (let i = 0; i < 42; i++) {
        this.ambientParticles.push({
          x: 0.20 + Math.random() * 0.62,
          y: 0.10 + Math.random() * 0.78,
          r: 1.8 + Math.random() * 4.5,
          phase: Math.random() * Math.PI * 2,
          speedX: (Math.random() - 0.48) * 0.025,
          speedY: -0.018 - Math.random() * 0.032,
          hueType: i % 3 // 0: pastel pink, 1: cyan-starlight, 2: iridescent violet-gold
        });
      }
    }

    _initBurstSystem() {
      this.bursts = [];
    }

    triggerDarkBurst(normX = 0.50, normY = 0.52) {
      const cx = normX * this.vecW;
      const cy = normY * this.vecH;
      const particles = [];
      for (let i = 0; i < 32; i++) {
        const ang = (i / 32) * Math.PI * 2 + (Math.random() - 0.5) * 0.22;
        const spd = 3.5 + Math.random() * 11.5;
        particles.push({
          x: cx,
          y: cy,
          vx: Math.cos(ang) * spd,
          vy: Math.sin(ang) * spd - 1.2,
          r: 4.0 + Math.random() * 10.0,
          isBubble: i % 2 === 0,
          color: i % 3 === 0 ? '#ff9de6' : (i % 3 === 1 ? '#8cf4ff' : '#ffe8a3'),
          alpha: 1.0
        });
      }
      this.bursts.push({ x: cx, y: cy, age: 0, maxAge: 0.78, particles });
      if (!this.isPlaying && this.isReady) {
        this.renderAtTime(this.currentTime, 0.016);
      }
    }

    async _boot() {
      try {
        if (typeof pako === 'undefined') {
          throw new Error('pako library is required for inflating optical flow and vector streams.');
        }
        const flowRaw = pako.inflate(b64ToUint8Array(FLOW_B64));
        this._flowBytes = flowRaw;

        const decodePromises = WEBP_B64.map((b64, idx) => {
          return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => {
              this.framesImage[idx] = img;
              resolve();
            };
            img.onerror = reject;
            img.src = 'data:image/webp;base64,' + b64;
          });
        });
        await Promise.all(decodePromises);

        this._initGL();
        this.isReady = true;
        this.renderAtTime(0.0, 0.0);
        if (typeof this.onReady === 'function') this.onReady(this);
      } catch (err) {
        console.error('Pink2HitVectorAnimator boot error:', err);
      }
    }

    _ensureVectorFrames() {
      if (this.vectorLayers) return;
      this._rawIndexBuf = pako.inflate(b64ToUint8Array(GZ_B64));
      this.vectorLayers = new Array(NUM_FRAMES);
    }

    _getVectorFrameCanvas(frameIdx) {
      this._ensureVectorFrames();
      if (this.vectorLayers[frameIdx]) return this.vectorLayers[frameIdx];

      const off = document.createElement('canvas');
      off.width = this.vecW;
      off.height = this.vecH;
      const ctx = off.getContext('2d');

      // Render quantized 2x vector region fill + sub-pixel contour wireframe
      const imgData = ctx.createImageData(CANONICAL_W, CANONICAL_H);
      const data32 = new Uint32Array(imgData.data.buffer);
      const pal32 = PALETTE.map(hex => {
        const r = parseInt(hex.slice(1, 3), 16);
        const g = parseInt(hex.slice(3, 5), 16);
        const b = parseInt(hex.slice(5, 7), 16);
        return (255 << 24) | (b << 16) | (g << 8) | r;
      });

      const start = frameIdx * CANONICAL_W * CANONICAL_H;
      for (let i = 0; i < CANONICAL_W * CANONICAL_H; i++) {
        const pIdx = this._rawIndexBuf[start + i];
        if (pIdx > 0) {
          data32[i] = pal32[pIdx - 1];
        }
      }

      const tmp = document.createElement('canvas');
      tmp.width = CANONICAL_W;
      tmp.height = CANONICAL_H;
      tmp.getContext('2d').putImageData(imgData, 0, 0);

      ctx.save();
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = 'high';
      ctx.globalAlpha = 0.88;
      ctx.drawImage(tmp, 0, 0, this.vecW, this.vecH);

      // Draw crisp 2x vector contour wireframe overlay
      ctx.globalAlpha = 0.95;
      ctx.fillStyle = '#ff94e8';
      for (let y = 1; y < CANONICAL_H - 1; y++) {
        const rowOff = start + y * CANONICAL_W;
        for (let x = 1; x < CANONICAL_W - 1; x++) {
          const c = this._rawIndexBuf[rowOff + x];
          if (c > 0) {
            const r = this._rawIndexBuf[rowOff + x + 1];
            const d = this._rawIndexBuf[rowOff + CANONICAL_W + x];
            if (r === 0 || d === 0) {
              ctx.fillStyle = '#7bf2ff';
              ctx.fillRect(x * 2, y * 2, 2, 2);
            } else if (Math.abs(c - r) > 5 || Math.abs(c - d) > 5) {
              ctx.fillStyle = 'rgba(255, 165, 238, 0.55)';
              ctx.fillRect(x * 2, y * 2, 1.5, 1.5);
            }
          }
        }
      }
      ctx.restore();

      this.vectorLayers[frameIdx] = off;
      return off;
    }

    _initGL() {
      const gl = this.glCanvas.getContext('webgl2', {
        alpha: true,
        premultipliedAlpha: true,
        antialias: true
      });
      if (!gl) {
        this.gl = null;
        return;
      }
      this.gl = gl;

      const compile = (type, src) => {
        const s = gl.createShader(type);
        gl.shaderSource(s, src);
        gl.compileShader(s);
        if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
          console.error(gl.getShaderInfoLog(s));
        }
        return s;
      };

      const prog = gl.createProgram();
      gl.attachShader(prog, compile(gl.VERTEX_SHADER, VS_SOURCE));
      gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, FS_SOURCE));
      gl.linkProgram(prog);
      gl.useProgram(prog);
      this.glProg = prog;

      const quad = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);
      const buf = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buf);
      gl.bufferData(gl.ARRAY_BUFFER, quad, gl.STATIC_DRAW);

      const aPos = gl.getAttribLocation(prog, 'aPos');
      gl.enableVertexAttribArray(aPos);
      gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

      this.uLoc = {
        uTex0: gl.getUniformLocation(prog, 'uTex0'),
        uTex1: gl.getUniformLocation(prog, 'uTex1'),
        uFlowTex: gl.getUniformLocation(prog, 'uFlowTex'),
        uFrac: gl.getUniformLocation(prog, 'uFrac'),
        uUseFlow: gl.getUniformLocation(prog, 'uUseFlow'),
        uShowChecker: gl.getUniformLocation(prog, 'uShowChecker'),
        uRes: gl.getUniformLocation(prog, 'uRes')
      };

      gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);

      for (let i = 0; i < NUM_FRAMES; i++) {
        const tex = gl.createTexture();
        gl.bindTexture(gl.TEXTURE_2D, tex);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, this.framesImage[i]);
        this.glTextures[i] = tex;

        const fTex = gl.createTexture();
        gl.bindTexture(gl.TEXTURE_2D, fTex);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        const fSlice = this._flowBytes.subarray(i * FLOW_W * FLOW_H * 4, (i + 1) * FLOW_W * FLOW_H * 4);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, FLOW_W, FLOW_H, 0, gl.RGBA, gl.UNSIGNED_BYTE, fSlice);
        this.flowTextures[i] = fTex;
      }
    }

    _drawCheckerboard2D(ctx) {
      const step = 32;
      for (let y = 0; y < this.vecH; y += step) {
        for (let x = 0; x < this.vecW; x += step) {
          const isEven = ((x / step) + (y / step)) % 2 === 0;
          ctx.fillStyle = isEven ? '#0e0d14' : '#181622';
          ctx.fillRect(x, y, step, step);
        }
      }
    }

    _drawStarflare(ctx, x, y, size, color, alpha) {
      if (alpha <= 0.01) return;
      ctx.save();
      ctx.translate(x, y);
      ctx.globalAlpha = Math.min(1.0, alpha);
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(0, -size);
      ctx.quadraticCurveTo(size * 0.14, -size * 0.14, size, 0);
      ctx.quadraticCurveTo(size * 0.14, size * 0.14, 0, size);
      ctx.quadraticCurveTo(-size * 0.14, size * 0.14, -size, 0);
      ctx.quadraticCurveTo(-size * 0.14, -size * 0.14, 0, -size);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    _drawIridescentBubble(ctx, x, y, r, alpha, phase) {
      if (alpha <= 0.01 || r <= 0.5) return;
      ctx.save();
      ctx.globalAlpha = Math.min(1.0, alpha);
      const grad = ctx.createRadialGradient(x - r * 0.28, y - r * 0.28, r * 0.1, x, y, r);
      grad.addColorStop(0.0, 'rgba(255, 245, 255, 0.85)');
      grad.addColorStop(0.35, 'rgba(255, 165, 235, 0.25)');
      grad.addColorStop(0.75, 'rgba(130, 235, 255, 0.35)');
      grad.addColorStop(1.0, 'rgba(235, 140, 255, 0.70)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.lineWidth = 1.4;
      ctx.strokeStyle = Math.sin(phase) > 0 ? 'rgba(255, 185, 242, 0.75)' : 'rgba(150, 245, 255, 0.75)';
      ctx.stroke();
      ctx.restore();
    }

    _renderDarkVFXOverlay(ctx, t, dt) {
      ctx.save();
      ctx.globalCompositeOperation = 'screen';

      // Action intensity envelope: peaks during 2-hit combo (1.2s..2.8s) and overhead bubble arch (9.6s..11.8s)
      const isCombo1 = (t >= 1.15 && t <= 2.85);
      const isFinale = (t >= 9.50 && t <= 11.95);
      const boost = isCombo1 ? 1.55 : (isFinale ? 1.40 : 0.45);

      for (let i = 0; i < this.ambientParticles.length; i++) {
        const p = this.ambientParticles[i];
        if (dt > 0) {
          p.x += p.speedX * dt * boost;
          p.y += p.speedY * dt * boost;
          if (p.y < 0.04) { p.y = 0.86; p.x = 0.22 + Math.random() * 0.56; }
          if (p.x < 0.08 || p.x > 0.92) p.speedX *= -1;
        }
        const twinkle = 0.35 + 0.65 * Math.pow(0.5 + 0.5 * Math.sin(t * 4.2 + p.phase), 2.0);
        const alpha = twinkle * (isCombo1 || isFinale ? 0.65 : 0.22);
        const px = p.x * this.vecW;
        const py = p.y * this.vecH;

        if (i % 4 === 0 && (isCombo1 || isFinale)) {
          this._drawIridescentBubble(ctx, px, py, p.r * 2.2, alpha * 0.75, t * 3.0 + p.phase);
        } else {
          const col = p.hueType === 0 ? '#ffa6ec' : (p.hueType === 1 ? '#8cf6ff' : '#ffe6a3');
          this._drawStarflare(ctx, px, py, p.r * 2.4, col, alpha);
        }
      }

      // Render user-triggered interactive bursts
      for (let b = this.bursts.length - 1; b >= 0; b--) {
        const burst = this.bursts[b];
        burst.age += dt > 0 ? dt : 0.016;
        const prog = burst.age / burst.maxAge;
        if (prog >= 1.0) {
          this.bursts.splice(b, 1);
          continue;
        }
        const fade = 1.0 - prog;
        // Expanding pastel shockwave ring
        ctx.strokeStyle = `rgba(255, 165, 240, ${fade * 0.65})`;
        ctx.lineWidth = 3.0 * fade;
        ctx.beginPath();
        ctx.arc(burst.x, burst.y, prog * 210.0, 0, Math.PI * 2);
        ctx.stroke();

        for (const pt of burst.particles) {
          pt.x += pt.vx;
          pt.y += pt.vy;
          pt.vx *= 0.95;
          pt.vy *= 0.95;
          if (pt.isBubble) {
            this._drawIridescentBubble(ctx, pt.x, pt.y, pt.r * (0.7 + 0.5 * prog), fade * 0.9, burst.age * 8.0);
          } else {
            this._drawStarflare(ctx, pt.x, pt.y, pt.r * 1.6, pt.color, fade);
          }
        }
      }

      ctx.restore();
    }

    renderAtTime(timeSec, dt = 0.0) {
      if (!this.isReady) return;
      const t = ((timeSec % this.loopDuration) + this.loopDuration) % this.loopDuration;
      this.currentTime = t;

      const exactFrame = (t / this.loopDuration) * NUM_FRAMES;
      const idx0 = Math.floor(exactFrame) % NUM_FRAMES;
      const idx1 = (idx0 + 1) % NUM_FRAMES;
      const frac = exactFrame - Math.floor(exactFrame);

      const ctx = this.ctx2d;
      ctx.clearRect(0, 0, this.vecW, this.vecH);

      if (this.renderMode === 'wireframe') {
        if (this.showChecker) this._drawCheckerboard2D(ctx);
        const vCanvas = this._getVectorFrameCanvas(idx0);
        ctx.drawImage(vCanvas, 0, 0);
        this._renderDarkVFXOverlay(ctx, t, dt);
      } else if (this.renderMode === 'sampled' || !this.gl) {
        if (this.showChecker) this._drawCheckerboard2D(ctx);
        ctx.drawImage(this.framesImage[idx0], 0, 0, this.vecW, this.vecH);
        this._renderDarkVFXOverlay(ctx, t, dt);
      } else {
        const gl = this.gl;
        gl.viewport(0, 0, this.vecW, this.vecH);
        gl.clearColor(0, 0, 0, 0);
        gl.clear(gl.COLOR_BUFFER_BIT);

        gl.useProgram(this.glProg);
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, this.glTextures[idx0]);
        gl.uniform1i(this.uLoc.uTex0, 0);

        gl.activeTexture(gl.TEXTURE1);
        gl.bindTexture(gl.TEXTURE_2D, this.glTextures[idx1]);
        gl.uniform1i(this.uLoc.uTex1, 1);

        gl.activeTexture(gl.TEXTURE2);
        gl.bindTexture(gl.TEXTURE_2D, this.flowTextures[idx0]);
        gl.uniform1i(this.uLoc.uFlowTex, 2);

        gl.uniform1f(this.uLoc.uFrac, frac);
        gl.uniform1f(this.uLoc.uUseFlow, this.useOpticalFlow ? 1.0 : 0.0);
        gl.uniform1f(this.uLoc.uShowChecker, this.showChecker ? 1.0 : 0.0);
        gl.uniform2f(this.uLoc.uRes, this.vecW, this.vecH);

        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
        ctx.drawImage(this.glCanvas, 0, 0);
        this._renderDarkVFXOverlay(ctx, t, dt);
      }

      if (typeof this.onTimeUpdate === 'function') {
        this.onTimeUpdate(t, idx0, NUM_FRAMES);
      }
    }

    play() {
      if (this.isPlaying) return;
      this.isPlaying = true;
      this.lastTick = performance.now();
      const loop = (now) => {
        if (!this.isPlaying) return;
        const dt = Math.min(0.1, (now - this.lastTick) / 1000.0) * this.speed;
        this.lastTick = now;
        this.renderAtTime(this.currentTime + dt, dt);
        this.rafId = requestAnimationFrame(loop);
      };
      this.rafId = requestAnimationFrame(loop);
    }

    pause() {
      this.isPlaying = false;
      if (this.rafId) {
        cancelAnimationFrame(this.rafId);
        this.rafId = null;
      }
    }

    togglePlay() {
      if (this.isPlaying) this.pause();
      else this.play();
      return this.isPlaying;
    }

    seek(timeSec) {
      this.renderAtTime(timeSec, 0.0);
    }

    setSpeed(spd) {
      this.speed = Number(spd) || 1.0;
    }

    setRenderMode(mode) {
      this.renderMode = mode;
      this.renderAtTime(this.currentTime, 0.0);
    }

    setOpticalFlow(enabled) {
      this.useOpticalFlow = Boolean(enabled);
      this.renderAtTime(this.currentTime, 0.0);
    }

    setCheckerboard(enabled) {
      this.showChecker = Boolean(enabled);
      this.renderAtTime(this.currentTime, 0.0);
    }

    destroy() {
      this.pause();
    }
  }

  return Pink2HitVectorAnimator;
});